package com.bridgeops.approvals;

import com.bridgeops.approvals.application.ApprovalService;
import com.bridgeops.executions.application.*;
import com.bridgeops.identity.application.*;
import com.bridgeops.identity.domain.SessionOutcome.Granted;
import com.bridgeops.organizations.application.OrganizationService;
import com.bridgeops.support.TestAuthMaterial;
import jakarta.servlet.http.Cookie;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.*;
import org.springframework.boot.webmvc.test.autoconfigure.*;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;
import tools.jackson.databind.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.mockito.Mockito.*;

@SpringBootTest(properties={"bridgeops.auth.enabled=true","bridgeops.auth.origin=https://bridgeops.invalid","bridgeops.auth.issuer=approval-http","bridgeops.auth.key-id=approval-http","bridgeops.executions.worker.enabled=false"})
@AutoConfigureMockMvc(print=MockMvcPrint.NONE)
@Testcontainers
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class ApprovalHttpIT {
    static final String ORIGIN="https://bridgeops.invalid";static final TestAuthMaterial keys=new TestAuthMaterial();
    @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:77f585114c32fbca283dc835b0596f4e52b51b4c6662d7810b2f4084f60a1873").asCompatibleSubstituteFor("postgres")).withInitScript("organization-runtime.sql");
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",()->"bridgeops_app");r.add("spring.datasource.password",()->"synthetic-runtime-fixture");r.add("spring.flyway.user",postgres::getUsername);r.add("spring.flyway.password",postgres::getPassword);r.add("bridgeops.auth.private-key",()->keys.directory.resolve("private.pem").toString());r.add("bridgeops.auth.public-key",()->keys.directory.resolve("public.pem").toString());r.add("bridgeops.auth.csrf-key",()->keys.directory.resolve("csrf.key").toString());}
    @TestConfiguration static class Configuration {@Bean @Primary ApprovalLifecycleIT.MutableClock clock(){return new ApprovalLifecycleIT.MutableClock();}}
    @Autowired MockMvc mvc;@Autowired AccountPasswords passwords;@Autowired PasswordSessionService sessions;@Autowired AccessTokens tokens;@Autowired OrganizationService organizations;
    @Autowired ExecutionRuntime runtime;@Autowired SyntheticCapability capability;@Autowired ApprovalLifecycleIT.MutableClock clock;
    @MockitoSpyBean ApprovalService approvals;
    final ObjectMapper json=new ObjectMapper();JdbcTemplate operator;Browser owner,approver;UUID org;String workflowPath;static String hash;
    record Browser(UUID user,UUID family,Cookie refresh,Cookie csrf,String access){@Override public String toString(){return "Browser[REDACTED]";}}
    @BeforeEach void fixture()throws Exception{operator=new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()));operator.execute("TRUNCATE users,installation_state,authentication_throttles CASCADE");operator.update("INSERT INTO installation_state(singleton_id) VALUES(1)");clock.now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);if(hash==null)hash=passwords.hash("approval-http-disposable");owner=account("owner@example.invalid");operator.update("INSERT INTO user_grants VALUES(?,'organization.create',?)",owner.user(),java.sql.Timestamp.from(clock.instant()));org=organizations.create(owner.user(),owner.family(),"HTTP approval","http-approval").id();approver=member("APPROVER");var draft=read(send(owner,post(base()+"/workflows").content(body(Map.of("name","Governed record","description","","definition",json.readTree(ApprovalLifecycleIT.GRAPH))))).andExpect(status().isCreated()).andReturn());workflowPath=base()+"/workflows/"+draft.path("workflow").path("id").asString();send(owner,post(workflowPath+"/publish").content("{\"expectedRevision\":0}")).andExpect(status().isCreated());}
    Browser account(String email)throws Exception{UUID id=UUID.randomUUID();var now=java.sql.Timestamp.from(clock.instant());operator.update("INSERT INTO users(id,email,normalized_email,password_hash,display_name,account_status,created_at,email_verified_at) VALUES(?,?,?,?,?,'ACTIVE',?,?)",id,email,email,hash,"HTTP synthetic",now,now);var grant=(Granted)sessions.authenticate(email,"approval-http-disposable");var refresh=new Cookie("__Host-bridgeops-refresh",grant.refreshToken());var csrf=mvc.perform(get("/api/v1/auth/csrf").cookie(refresh)).andExpect(status().isOk()).andReturn().getResponse().getCookie("__Host-bridgeops-csrf");return new Browser(id,grant.familyId(),refresh,csrf,tokens.issue(grant).value());}
    Browser member(String role)throws Exception{var actor=account(role.toLowerCase(Locale.ROOT)+"@example.invalid");UUID member=UUID.randomUUID();operator.update("INSERT INTO organization_memberships(id,organization_id,user_id,status,joined_at) VALUES(?,?,?,'ACTIVE',?)",member,org,actor.user(),java.sql.Timestamp.from(clock.instant()));operator.update("INSERT INTO membership_roles SELECT ?,?,id FROM roles WHERE organization_id=? AND name=?",org,member,org,role);return actor;}
    String base(){return "/api/v1/organizations/"+org;}
    ResultActions send(Browser b,MockHttpServletRequestBuilder request)throws Exception{return mvc.perform(request.header("Authorization","Bearer "+b.access()).header("Origin",ORIGIN).cookie(b.refresh(),b.csrf()).header("X-CSRF-TOKEN",b.csrf().getValue()).contentType("application/json"));}
    String body(Object object){return json.writeValueAsString(object);}JsonNode read(MvcResult result)throws Exception{return json.readTree(result.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));}
    void drain(){var worker=new ExecutionWorker(runtime,capability,4,2,30,1000);for(int i=0;i<30;i++){runtime.reconcile();var claim=runtime.claim(UUID.randomUUID(),4,2,30);if(claim==null)return;worker.dispatch(claim);}throw new AssertionError("Worker did not quiesce");}
    String waiting()throws Exception{send(owner,post(workflowPath+"/executions").header("Idempotency-Key",UUID.randomUUID().toString()).content("{\"input\":{}}")).andExpect(status().isAccepted());drain();return base()+"/approvals/"+operator.queryForObject("SELECT id FROM approval_requests",UUID.class);}
    String decision(){return "{\"expectedRevision\":0,\"decision\":\"APPROVE\"}";}
    @Test void authenticatedApprovalListsExactIntentAndCommitsDecisionBeforeWorkerResumes()throws Exception{String path=waiting();send(approver,get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.arguments.message").value("Exact protected record")).andExpect(jsonPath("$.actionable").value(true)).andExpect(jsonPath("$.executionStatus").value("WAITING_FOR_APPROVAL"));send(owner,get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.actionable").value(false));send(approver,get(base()+"/approvals?status=PENDING&size=1")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));send(approver,post(path+"/decision").content(decision())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("APPROVED")).andExpect(jsonPath("$.executionStatus").value("WAITING_FOR_APPROVAL"));assertThat(operator.queryForObject("SELECT count(*) FROM synthetic_records",Long.class)).isEqualTo(1);drain();send(approver,get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.executionStatus").value("SUCCEEDED"));send(approver,post(path+"/decision").content(decision())).andExpect(status().isConflict());}
    @Test void selfViewerAndCrossTenantDecisionsAreDeniedAndResourcesConcealed()throws Exception{String path=waiting();send(owner,post(path+"/decision").content(decision())).andExpect(status().isForbidden()).andExpect(jsonPath("$.code").value("SELF_APPROVAL_FORBIDDEN"));var viewer=member("VIEWER");send(viewer,post(path+"/decision").content(decision())).andExpect(status().isForbidden());send(viewer,get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.actionable").value(false));UUID foreign=organizations.create(owner.user(),owner.family(),"Foreign","foreign-approval").id();String other=path.replace(org.toString(),foreign.toString());send(owner,get(other)).andExpect(status().isNotFound());send(owner,post(other+"/decision").content(decision())).andExpect(status().isNotFound());send(approver,get(base()+"/approvals/"+UUID.randomUUID())).andExpect(status().isNotFound());}
    @Test void bearerOriginAndCsrfRemainMandatoryOnDecisionAndPolicyMutations()throws Exception{String path=waiting();mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(post(path+"/decision").header("Authorization","Bearer "+approver.access()).header("Origin",ORIGIN).cookie(approver.refresh()).contentType("application/json").content(decision())).andExpect(status().isForbidden());mvc.perform(post(path+"/decision").header("Authorization","Bearer "+approver.access()).header("Origin","https://hostile.invalid").cookie(approver.refresh(),approver.csrf()).header("X-CSRF-TOKEN",approver.csrf().getValue()).contentType("application/json").content(decision())).andExpect(status().isForbidden());mvc.perform(put(base()+"/approval-policy").header("Authorization","Bearer "+owner.access()).header("Origin",ORIGIN).contentType("application/json").content("{}")).andExpect(status().isForbidden());assertThat(operator.queryForObject("SELECT count(*) FROM approval_decisions",Long.class)).isZero();}
    @Test void strictDecisionScalarsUnknownArgumentsDuplicateKeysAndOversizedBodiesFailSafely()throws Exception{String path=waiting();for(String invalid:List.of("{\"expectedRevision\":\"0\",\"decision\":\"APPROVE\"}","{\"expectedRevision\":0.0,\"decision\":\"APPROVE\"}","{\"expectedRevision\":null,\"decision\":\"APPROVE\"}","{\"expectedRevision\":0,\"decision\":true}","{\"expectedRevision\":0,\"decision\":\"approve\"}","{\"expectedRevision\":0,\"decision\":\"APPROVE\",\"arguments\":{}}","{\"expectedRevision\":0,\"decision\":\"APPROVE\",\"decision\":\"REJECT\"}",body(Map.of("expectedRevision",0,"decision","APPROVE","reason","x".repeat(201)))))send(approver,post(path+"/decision").content(invalid)).andExpect(status().isBadRequest());send(approver,post(path+"/decision").content("{\"expectedRevision\":1,\"decision\":\"APPROVE\"}")).andExpect(status().isConflict());send(approver,post(path+"/decision").content(" ".repeat(262145))).andExpect(status().isContentTooLarge());send(approver,get(base()+"/approvals?size=101")).andExpect(status().isBadRequest());assertThat(operator.queryForObject("SELECT count(*) FROM approval_decisions",Long.class)).isZero();}
    @Test void fixedPolicyPermissionRevisionAndStrictConfigAreEnforced()throws Exception{send(approver,get(base()+"/approval-policy")).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(0));String valid="{\"expectedRevision\":0,\"requireRecordApproval\":true,\"lifetimeSeconds\":60}";var admin=member("ADMIN");send(admin,put(base()+"/approval-policy").content(valid)).andExpect(status().isForbidden());for(String invalid:List.of(valid.replace("true","\"true\""),valid.replace(":60",":60.5"),valid.replace(":60",":\"60\""),valid.replace(":0",":0.0")))send(owner,put(base()+"/approval-policy").content(invalid)).andExpect(status().isBadRequest());send(owner,put(base()+"/approval-policy").content(valid.replace(":60",":59"))).andExpect(status().isUnprocessableContent());send(owner,put(base()+"/approval-policy").content(valid)).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(1));send(owner,put(base()+"/approval-policy").content(valid)).andExpect(status().isConflict());}
    @Test void expiredRequestCannotBeApprovedWithAStillValidAccessToken()throws Exception{send(owner,put(base()+"/approval-policy").content("{\"expectedRevision\":0,\"requireRecordApproval\":false,\"lifetimeSeconds\":60}")).andExpect(status().isOk());String path=waiting();clock.add(61);send(approver,post(path+"/decision").content(decision())).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("APPROVAL_EXPIRED"));drain();send(approver,get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("EXPIRED")).andExpect(jsonPath("$.executionStatus").value("FAILED"));}
    @Test void adapterMapsDependencyOutageToSafe503WithoutLeakingExceptionText()throws Exception{String path=waiting();UUID id=UUID.fromString(path.substring(path.lastIndexOf('/')+1));doThrow(new org.springframework.dao.DataAccessResourceFailureException("controlled-sensitive-canary")).when(approvals).get(approver.user(),approver.family(),org,id);var result=send(approver,get(path)).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("DEPENDENCY_UNAVAILABLE")).andReturn();assertThat(result.getResponse().getContentAsString()).doesNotContain("controlled-sensitive-canary","Exception","jdbc:");}
    @Test void boundedReviewMetadataContainsNamesAndVersionButNoWorkflowGraphOrAccountCredentials()throws Exception{String path=waiting();var result=send(approver,get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.workflowName").value("Governed record")).andExpect(jsonPath("$.versionNumber").value(1)).andExpect(jsonPath("$.requesterName").value("HTTP synthetic")).andReturn();assertThat(result.getResponse().getContentAsString()).doesNotContain("\"definition\":","\"nodes\":","\"edges\":","owner@example.invalid","passwordHash","password_hash","normalized_email");}
}
